import Vue from 'vue'
import VueRouter from 'vue-router'
import Layout from '@/views/Layout.vue'

Vue.use(VueRouter)

const routes = [
  {
    path: '/',
    component: Layout,
    redirect: '/dashboard',
    meta: { requiresAuth: true },
    children: [
      {
        path: 'dashboard',
        name: 'Dashboard',
        component: () => import('@/views/Dashboard.vue'),
        meta: { title: '首页' }
      },
      {
        path: 'club',
        name: 'ClubList',
        component: () => import('@/views/ClubList.vue'),
        meta: { title: '社团管理' }
      },
      {
        path: 'venue',
        name: 'VenueList',
        component: () => import('@/views/VenueList.vue'),
        meta: { title: '场地管理' }
      },
      {
        path: 'activity',
        name: 'ActivityList',
        component: () => import('@/views/ActivityList.vue'),
        meta: { title: '活动管理' }
      },
      {
        path: 'profile',
        name: 'Profile',
        component: () => import('@/views/Profile.vue'),
        meta: { title: '个人中心' }
      },
      {
        path: 'user',
        name: 'UserList',
        component: () => import('@/views/UserList.vue'),
        meta: { title: '用户管理', role: 'admin' }
      },
      {
        path: 'facility',
        name: 'FacilityList',
        component: () => import('@/views/FacilityList.vue'),
        meta: { title: '设施管理' }
      },
      {
        path: 'venue-calendar',
        name: 'VenueCalendar',
        component: () => import('@/views/VenueCalendar.vue'),
        meta: { title: '场地排期' }
      },
      {
        path: 'suggestion',
        name: 'SuggestionList',
        component: () => import('@/views/SuggestionList.vue'),
        meta: { title: '用户建议' }
      },
      {
        path: 'role',
        name: 'RoleList',
        component: () => import('@/views/RoleList.vue'),
        meta: { title: '角色管理', role: 'admin' }
      }
    ]
  },
  {
    path: '/login',
    name: 'Login',
    component: () => import('@/views/Login.vue'),
    meta: { title: '登录' }
  },
  {
    path: '/register',
    name: 'Register',
    component: () => import('@/views/Register.vue'),
    meta: { title: '注册' }
  }
]

const router = new VueRouter({
  mode: 'history',
  base: process.env.BASE_URL,
  routes
})

// 全局路由守卫：登录状态校验
router.beforeEach((to, from, next) => {
  const isLoggedIn = !!localStorage.getItem('user')

  if (to.matched.some(record => record.meta.requiresAuth)) {
    // 需要登录的页面，未登录则跳转到登录页
    if (!isLoggedIn) {
      next({ name: 'Login', query: { redirect: to.fullPath } })
    } else {
      next()
    }
  } else if (to.name === 'Login' && isLoggedIn) {
    // 已登录则不允许访问登录页
    next({ path: '/' })
  } else {
    next()
  }
})

export default router
