<script>
import ParticleBackground from '@/components/ParticleBackground.vue'

export default {
  name: 'Layout',
  components: { ParticleBackground },
  data() {
    const user = JSON.parse(localStorage.getItem('user') || '{}')
    return {
      userNickname: user.nickname || user.username || '用户',
      userAvatar: user.avatar || '',
      role: localStorage.getItem('role') || 'user',
      noticeCount: 3,
      collapsed: false,
      darkMode: (localStorage.getItem('theme') || 'light') === 'dark'
    }
  },
  computed: {
    activeMenu() {
      const path = this.$route.path
      if (path.startsWith('/club')) return '/club'
      if (path.startsWith('/venue')) return '/venue'
      if (path.startsWith('/activity')) return '/activity'
      if (path.startsWith('/facility')) return '/facility'
      if (path.startsWith('/user')) return '/user'
      if (path.startsWith('/profile')) return ''
      return path
    }
  },
  methods: {
    toggleTheme() {
      this.darkMode = !this.darkMode
      const theme = this.darkMode ? 'dark' : 'light'
      localStorage.setItem('theme', theme)
      document.documentElement.setAttribute('data-theme', theme)
    },
    handleCommand(command) {
      if (command === 'profile') {
        this.$router.push('/profile')
      } else if (command === 'toggleTheme') {
        this.toggleTheme()
      } else if (command === 'logout') {
        localStorage.removeItem('user')
        localStorage.removeItem('role')
        this.$router.push('/login')
        this.$message.success('已退出登录')
      }
    }
  }
}
</script>

